import physical
def _player_identity(state: GameState) -> str:
    """Authoritative character identity, not inferred from the journal or portrait."""
    p = state.player
    gender = p.gender.strip()
    pronouns = {'female': 'she/her/hers', 'male': 'he/him/his',
                'non-binary': 'they/them/theirs', 'nonbinary': 'they/them/theirs'}.get(gender.casefold())
    reference = (f"Use {pronouns} for this character when writing in third person."
                 if pronouns else "Use the character's name or second-person you/your unless their pronouns are established; do not guess.")
    return (f"PLAYER CHARACTER IDENTITY (authoritative): {p.name}; {p.race} {p.char_class}; "
            f"gender: {gender or 'unspecified'}. {reference} Second-person you/your is also fine. "
            "This identity overrides inconsistent references in earlier narration or memory. "
            "Apply these references only to the player, not to other characters.")


